let hero={name:'Morrow',class:null,race:null,blood:10,maxBlood:10,items:[],journal:[],node:'arrival',roll:null,encounter:null,flags:{},choicesMade:0,ended:false};
function show(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(id).classList.add('active');window.scrollTo({top:0,behavior:'smooth'})}
function showSetup(){show('setup');renderSetup()}
function renderSetup(){document.getElementById('classGrid').innerHTML=classes.map(c=>`<button class="class-card ${hero.class?.id===c.id?'selected':''}" onclick="selectClass('${c.id}')"><div class="class-icon">${c.icon}</div><h3>${c.name}</h3><p>${c.desc}</p></button>`).join('');document.getElementById('raceRow').innerHTML=races.map(r=>`<button class="race-card ${hero.race?.id===r.id?'selected':''}" onclick="selectRace('${r.id}')"><div>${r.icon}</div><h3>${r.name}</h3><p>${r.desc}</p></button>`).join('')}
function selectClass(id){hero.class=classes.find(x=>x.id===id);renderSetup()}
function selectRace(id){hero.race=races.find(x=>x.id===id);renderSetup()}
function randomHero(){let cRoll=die(6),rRoll=die(2);hero.class=classes[cRoll-1];hero.race=races[rRoll-1];document.getElementById('heroName').value=['Morrow','Vesper','Rook','Sable','Ash','Riven'][die(6)-1];renderSetup();setDie(`d6 ${cRoll} · d2 ${rRoll}`,'Your fate is cast.<br><b>Calling & bloodline chosen.</b>');toast(`${hero.class.name} ${hero.race.name} selected by the dice`)}
function die(sides){return Math.floor(Math.random()*sides)+1}
function setDie(value,copy){document.getElementById('dieValue').textContent=value;document.getElementById('rollCopy').innerHTML=copy}
function rollD20(stat=''){let roll=die(20);let bonus=hero.race?.bonus||0;if(hero.class&&hero.class.stat===stat)bonus+=hero.class.bonus;hero.roll={roll,bonus,total:roll+bonus};setDie(roll,`d20 ${roll} ${bonus?`+ ${bonus} ${stat||'blood'}`:''}<br><b>Total ${roll+bonus}</b>`);return hero.roll}
function beginGame(){if(!hero.class||!hero.race){toast('Choose a calling and bloodline, or roll for me.');return}hero.name=(document.getElementById('heroName').value.trim()||'Morrow').slice(0,20);hero.maxBlood=hero.race.blood;hero.blood=hero.maxBlood;hero.node='arrival';hero.items=[];hero.journal=[];hero.flags={};hero.choicesMade=0;hero.ended=false;hero.encounter=null;setDie('—','The dice are waiting.<br><b>What will fate decide?</b>');show('adventure');renderNode()}
function log(text){hero.journal.unshift(text);hero.journal=hero.journal.slice(0,5)}
function renderNode(){if(hero.ended)return;const n=nodes[hero.node];if(!n){finish(hero.node);return}document.getElementById('sceneArt').textContent=n.art;document.getElementById('sceneCaption').textContent=n.caption;document.getElementById('chapterKicker').textContent=n.chapter;document.getElementById('chapterCount').textContent=`${String(Object.keys(nodes).indexOf(hero.node)+1).padStart(2,'0')} / ${Object.keys(nodes).length}`;document.getElementById('chapterTitle').textContent=n.title;document.getElementById('storyText').textContent=n.text;document.getElementById('encounterSlot').innerHTML='';document.getElementById('choices').innerHTML=n.choices.filter(c=>!c.needItem||hero.items.includes(c.needItem)||hero.items.includes(c.alternateItem)).map((c,i)=>`<button class="choice" onclick="choose(${i})"><span><strong>${c.title}</strong><small>${c.desc}</small></span><span class="tag ${c.safe?'safe':c.enemy?'risk':''}">${c.tag}</span></button>`).join('');renderSidebar()}
function renderSidebar(){const c=hero.class,r=hero.race;document.getElementById('charCard').innerHTML=`<h3 class="char-name">${hero.name}</h3><div class="char-class">${r?.name||'—'} · ${c?.name||'—'}</div><div class="stat-head"><span>Blood</span><b>${hero.blood} / ${hero.maxBlood}</b></div><div class="bar blood"><i style="width:${Math.max(0,hero.blood/hero.maxBlood*100)}%"></i></div><div class="stat-note">Your life and power in the night</div><div class="stat-head"><span>Resolve</span><b>${Math.min(100,50+hero.choicesMade*8)}%</b></div><div class="bar resolve"><i style="width:${Math.min(100,50+hero.choicesMade*8)}%"></i></div>`;document.getElementById('inventory').innerHTML=hero.items.length?hero.items.map(i=>`<span class="item">✦ ${i}</span>`).join(''):'<span class="item">No keepsakes yet</span>';document.getElementById('journal').innerHTML=hero.journal.length?hero.journal.map(x=>`<div><b>✧</b> ${x}</div>`).join(''):'<div>Your chronicle begins here.</div>'}
function choose(index){const n=nodes[hero.node];const available=n.choices.filter(c=>!c.needItem||hero.items.includes(c.needItem)||hero.items.includes(c.alternateItem));const c=available[index];if(!c)return;hero.choicesMade++;if(c.enemy){startEncounter(c);return}if(c.check){const out=rollD20(c.stat);const success=out.total>=c.check;const hasItem=!c.needItem||hero.items.includes(c.needItem)||hero.items.includes(c.alternateItem);if(success&&hasItem){applyEffect(c.successEffect,c);log(c.successEffect);transition(c.successTo)}else{const effect=success&&!hasItem?'You lack the keepsake needed for the rite. The queen waits.':c.failEffect;log(effect);toast(effect);if(c.failTo){transition(c.failTo)}else{document.getElementById('storyText').textContent+=` ${effect}`;renderNode()}}return}applyEffect(c.effect,c);log(c.effect);transition(c.to)}
function applyEffect(text,c={}){if(c.heal)hero.blood=Math.min(hero.maxBlood,hero.blood+c.heal);if(c.item&&!hero.items.includes(c.item))hero.items.push(c.item);if(c.item==='Dawn sigil')hero.flags.dawn=true;if(c.item==='Queen’s true name')hero.flags.name=true;toast(text)}
function transition(to){if(to.startsWith('ending_')){finish(to);return}hero.node=to;renderNode()}

